def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.25)
        return float(max(0.0, bid))

    prev_bids = []
    dangerous_prev = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev['bid'])
            prev_bids.append(b)
            if b > 0:
                dangerous_prev.append(b)

    highest_prev = max(dangerous_prev) if dangerous_prev else 0.0
    avg_prev = (sum(dangerous_prev) / len(dangerous_prev)) if dangerous_prev else 0.0

    alive_count = len(alive) + 1
    expected_need = alive_count * WATER_REQ
    tight_supply = supply < expected_need
    very_tight = supply <= WATER_REQ

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if very_tight:
        urgency += 3
    elif tight_supply:
        urgency += 1

    if day >= 8:
        urgency += 1

    rich_threats = 0
    for opp in alive:
        if opp.get('budget', 0) >= 120 and opp.get('hp', 0) > 0:
            rich_threats += 1
    if rich_threats >= 2:
        urgency += 1

    if urgency <= 1:
        base = 18.0 if not tight_supply else 26.0
        if avg_prev > 0:
            base = max(base, min(38.0, avg_prev * 0.22))
    elif urgency == 2:
        base = 42.0
        if avg_prev > 0:
            base = max(base, min(68.0, avg_prev * 0.48))
    elif urgency == 3:
        base = 72.0
        if highest_prev > 0:
            base = max(base, min(96.0, highest_prev * 0.72))
    elif urgency == 4:
        base = 96.0
        if highest_prev > 0:
            base = max(base, min(118.0, highest_prev + 2.0))
    else:
        base = 112.0
        if highest_prev > 0:
            base = max(base, min(135.0, highest_prev + 4.0))

    if budget < DAILY_SALARY:
        base = min(base, budget * 0.92)

    if hp >= 7 and no_water_days == 0 and not very_tight and highest_prev >= 100:
        base = min(base, 34.0)

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return 10.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 115.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_prev + 5.0, 135.0))
    else:
        bid = min(my_status['budget'], max(avg_prev - 2.0, 110.0))

    return float(bid)
